<!DOCTYPE html>
<html>
<head>
  <title>Maze Game</title>
  <style>
    body { font-family: sans-serif; }
    #maze { border: 1px solid black; margin: 20px auto; display: block; width: 400px; height: 400px; }
    .cell { width: 16px; height: 16px; position: absolute; }
    .wall-n { border-top: 1px solid black; }
    .wall-e { border-right: 1px solid black; }
    .wall-s { border-bottom: 1px solid black; }
    .wall-w { border-left: 1px solid black; }
    .bot { width: 8px; height: 8px; position: absolute; border-radius: 50%; background-color: red; }
  </style>
</head>
<body>
  <div id="maze"></div>
  <p>Completed: <span id="completed">0</span></p>
  <p>Timer: <span id="timer">0</span></p>
  <button id="reset">Reset</button>

  <script>
    const mazeElement = document.getElementById('maze');
    const completedElement = document.getElementById('completed');
    const timerElement = document.getElementById('timer');
    const resetButton = document.getElementById('reset');

    let rows = 20;
    let cols = 20;
    let mazeData = []; // Store maze data for resetting
    let bots = [];
    let gameElapsed = 0;
    let isFrozen = false;
    let lastBotFinishTick = null;

    const seed = Math.random(); // Use a random seed for variation

    function generateMaze() {
      mazeData = Array(rows).fill(null).map(() => Array(cols).fill(0)); // 0: empty, 1: wall
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          if (r === 0 || r === rows - 1 || c === 0 || c === cols - 1) {
            mazeData[r][c] = 1;
          } else {
            if (Math.random() < 0.7) { // Adjust probability for maze density
              mazeData[r][c] = 1;
            }
          }
        }
      }
      // Ensure entrance and exit
      mazeData[0][1] = 0;
      mazeData[rows - 1][cols - 2] = 0;

      // Find exit
      let exitRow = Math.floor(Math.random() * (rows - 2)) + 1;
      let exitCol = Math.floor(Math.random() * (cols - 2)) + 1;
      while (mazeData[exitRow][exitCol] === 1) {
        exitRow = Math.floor(Math.random() * (rows - 2)) + 1;
        exitCol = Math.floor(Math.random() * (cols - 2)) + 1;
      }
      mazeData[exitRow][exitCol] = 0;
    }


    function createMazeVisualization() {
      const cellWidth = mazeElement.offsetWidth / cols;
      const cellHeight = mazeElement.offsetHeight / rows;

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const cell = document.createElement('div');
          cell.classList.add('cell');
          cell.style.width = `${cellWidth}px`;
          cell.style.height = `${cellHeight}px`;
          cell.style.left = `${c * cellWidth}px`;
          cell.style.top = `${r * cellHeight}px`;

          if (mazeData[r][c] === 1) {
            cell.classList.add('wall');
            if (r > 0 && mazeData[r - 1][c] === 1) cell.classList.add('wall-n');
            if (c > 0 && mazeData[r][c - 1] === 1) cell.classList.add('wall-w');
          }

          mazeElement.appendChild(cell);
        }
      }
    }


    function createBot(row, col) {
      const bot = {
        row: row,
        col: col,
        path: [],
        deadEnds: [],
        finishTick: null,
      };
      bots.push(bot);
      return bot;
    }

    function moveBot(bot) {
      let dr = 0;
      let dc = 0;

      // Tremaux/DFS exploration
      const walls = [ 'n', 'e', 's', 'w' ];
      Math.random().sort(() => Math.random() - 0.5).slice(0, 2).forEach(dir => {
        if (mazeData[bot.row][bot.col] === 1 && walls.includes(dir)) {
          dr = dir === 'n' ? -1 : dir === 's' ? 1 : 0;
          dc = dir === 'e' ? 1 : dir === 'w' ? -1 : 0;
          break;
        }
      });


      const newRow = bot.row + dr;
      const newCol = bot.col + dc;

      if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && mazeData[newRow][newCol] === 0) {
        bot.path.push({ r: newRow, c: newCol });
        bot.row = newRow;
        bot.col = newCol;

        // Check for dead end
        let numDirections = 0;
        if (mazeData[bot.row - 1][bot.col] === 0) numDirections++;
        if (mazeData[bot.row + 1][bot.col] === 0) numDirections++;
        if (mazeData[bot.row][bot.col - 1] === 0) numDirections++;
        if (mazeData[bot.row][bot.col + 1] === 0) numDirections++;

        if (numDirections <= 1) { // Modified dead end condition
          bot.deadEnds.push({ r: bot.row, c: bot.col });
        }
      }
    }


    function checkExit(bot) {
      if (bot.row === rows - 1 && bot.col === cols - 2) {
        bot.finishTick = gameElapsed;
        lastBotFinishTick = bot;
      }
    }

    function updateGame() {
      for (let i = 0; i < bots.length; i++) {
        moveBot(bots[i]);
        checkExit(bots[i]);
      }

      if (lastBotFinishTick !== null) {
          completedElement.innerText = bots.length;
          gameElapsed = lastBotFinishTick.finishTick;
          timerElement.innerText = gameElapsed;
          isFrozen = true;
      }
    }


    function resetGame() {
      generateMaze();
      createMazeVisualization();

      // Reset bot positions and paths
      bots.forEach(bot => {
        bot.path = [];
        bot.deadEnds = [];
        bot.finishTick = null;
      });
      lastBotFinishTick = null;
      gameElapsed = 0;
      isFrozen = false;

    }

    // Initialize game
    generateMaze();
    createMazeVisualization();
    for (let i = 0; i < 24; i++) {
      createBot(Math.floor(Math.random() * rows), Math.floor(Math.random() * cols));
    }

    // Event listeners
    resetButton.addEventListener('click', resetGame);

    // Game loop
    setInterval(() => {
      if (!isFrozen) {
        updateGame();
      }
    }, 10); // Adjust interval for smoother movement
  </script>
</body>
</html>
